// GEN_HPF_HighPassFilter.c  (GENERATED by analysis/harness/generator.py from the spec; edit the spec, not this file)
//
// PURPOSE:  Batch harness HPF. Feeds synthetic inputs through HighPassFilter (12 variants:
//           P20, P30, P48, P125, NCA [control], NCB [control], NCF [control], NCZ [control], NCS [control], NCH [control], NC1 [control], NC2 [control]) and writes the RAW outputs. It does NOT judge anything.
//           Python (analysis/harness/checker.py) measures and writes PASS/FAIL.
// PREREG:   analysis/harness/specs/HP_ArticleFidelity.toml (this file)
// INPUTS:   Synthetic only, from the bar counter n: flat | level+amp*sin(2*pi*n/T), T=5,10,20,40,100 | ramp level+slope*n
//           level=11/10 amp=1/100 slope=1/10000. (b, H1 run 1) Decimal literals are float32 in this Zorro
//           build and the PI macro is 3.14159, so every constant is built at run time from integers.
//           EUR/USD is used only as a bar clock; clock_close is exported for the checker's magnitude guard.
// OUTPUT:   Data/GEN_HPF_raw.csv  (3000 rows n=0..2999 + header; 93 columns; values printed with 15 decimals)
// CALLS:    84 filter calls per bar, variant-major, unconditional, fixed order (gotchas 3.1).
// FEEDING:  every x[n], n=0..2999, reaches the filters exactly once; INITRUN and EXITRUN feed and write nothing.
// NO LOOKBACK GUARD: LookBack = 0, warmup bars are exported too; the checker requires n = 0..2999 contiguous.
// SOURCES:  expected values and tolerances are in the spec, each with an (a)/(b)/(c) label.
//           Pattern copied from strategies/tests/H1_SuperSmoother2Pole_Harness.c (b: H1 run 2 PASS).
// Y[] index = variant*7 + input.

#include <default.c>
#include "../../indicators/ehlers/HighPassFilter.c"

#define HPF_RAW "Data/GEN_HPF_raw.csv"
#define HPF_MARK "Data/GEN_HPF_exit_marker.txt"
#define HPF_NBARS 3000

static int hpf_n = 0;
static int hpf_done = 0;
static int hpf_hdr = 0;
static int hpf_rows = 0;

// NC-A: realistic copying error (D2 rule 4), ceiling control. [corrected_code] except alpha1 + 1/10000 (= bump3 at P = 48:
// 0.0885263 -> 0.0886263) BEFORE the coefficients are derived. DC gain stays 0. Defined here only.
var hpf_nca(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*2.0*PI / P) + sin(hp_k*2.0*PI / P) - 1.0)
	       / cos(hp_k*2.0*PI / P);
	alpha1 = alpha1 + 1.0 / 10000;
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	var* HP = series(0, 3);
	HP[0] = hp_w * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

// NC-B: realistic copying error. [corrected_code] except (1-alpha1/2)^2 + 1/1000 (bump3 at P = 48: 0.913433 -> 0.914433).
// Scales the output only: phase unchanged by construction (7.5e-07 rad = the floor), so only gain is required.
var hpf_ncb(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*2.0*PI / P) + sin(hp_k*2.0*PI / P) - 1.0)
	       / cos(hp_k*2.0*PI / P);
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	hp_w = hp_w + 1.0 / 1000;
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	var* HP = series(0, 3);
	HP[0] = hp_w * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

// NC-F: realistic copying error in a feedback term. [corrected_code] except (1-alpha1)^2 + 1/1000 (bump3 at P = 48:
// 0.830784 -> 0.831784) in the HP[2] term only; 2*(1-alpha1) unchanged. Moves the poles.
var hpf_ncf(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*2.0*PI / P) + sin(hp_k*2.0*PI / P) - 1.0)
	       / cos(hp_k*2.0*PI / P);
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	hp_f2 = hp_f2 + 1.0 / 1000;
	var* HP = series(0, 3);
	HP[0] = hp_w * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

// NC-Z: form mix-up with the 1-pole HP (V.34:09) numerator x - x[1]: one zero at DC instead of two, so the ramp
// residual is non-zero (the only control that moves resid). [corrected_code] coefficients otherwise.
var hpf_ncz(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*2.0*PI / P) + sin(hp_k*2.0*PI / P) - 1.0)
	       / cos(hp_k*2.0*PI / P);
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	var* HP = series(0, 3);
	HP[0] = hp_w * (Price[0] - Price[1])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

// NC-S: deviation D-2 alone. [corrected_code] except series(Price[0], 3). Differs only in start-up (steady state = floor).
var hpf_ncs(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*2.0*PI / P) + sin(hp_k*2.0*PI / P) - 1.0)
	       / cos(hp_k*2.0*PI / P);
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	var* HP = series(Price[0], 3);
	HP[0] = hp_w * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

// NC-H: the real current file. Body = indicators/ehlers/HighPassFilter.c at 14395a0 (lines 24-42, comments removed),
// function renamed only. Pre-run (ii) verifies this against `git show 14395a0:indicators/ehlers/HighPassFilter.c`.
// Gain/phase effects (D-1) are 2.2x / 4.7x tolerance: caught by start-up (D-2) and by IMP must_fail (corrected model).
var hpf_nch(vars Price, int HPPeriod)
{
    var alpha1 = (cos(0.707*2.0*PI / HPPeriod) + sin(0.707*2.0*PI / HPPeriod) - 1.0)
           / cos(0.707*2.0*PI / HPPeriod);
    var* HP = series(Price[0], 3);
    HP[0] = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0)
            * (Price[0] - 2.0*Price[1] + Price[2])
            + 2.0*(1.0 - alpha1) * HP[1]
            - (1.0 - alpha1) * (1.0 - alpha1) * HP[2];
    return HP[0];
}

// NC2: gross units bug (gotchas §2). [corrected_code] with hp_k*360.0/P (degrees) in place of hp_k*2.0*PI/P. At P = 20
// (decision 3; unstable at P = 48).
var hpf_nc2(vars Price, int P)
{
	var hp_k = sqrt(2.0) / 2.0;
	var alpha1 = (cos(hp_k*360.0 / P) + sin(hp_k*360.0 / P) - 1.0)
	       / cos(hp_k*360.0 / P);
	var hp_w = (1.0 - alpha1/2.0) * (1.0 - alpha1/2.0);
	var hp_f2 = (1.0 - alpha1) * (1.0 - alpha1);
	var* HP = series(0, 3);
	HP[0] = hp_w * (Price[0] - 2.0*Price[1] + Price[2])
	        + 2.0*(1.0 - alpha1) * HP[1]
	        - hp_f2 * HP[2];
	return HP[0];
}

void run()
{
	// Settings must be assigned on every call, including INITRUN, or Zorro never sees them.
	BarPeriod = 1440;
	StartDate = 20080101;
	EndDate   = 20240101;
	LookBack  = 0;
	asset("EUR/USD");

	if(is(INITRUN)) {
		hpf_n = 0; hpf_done = 0; hpf_hdr = 0; hpf_rows = 0;	// declared initialisers
		file_delete(HPF_RAW);
		file_delete(HPF_MARK);
		return;
	}
	if(is(EXITRUN)) {
		printf("\nHPF EXIT: rows written = %d, done = %d  (expected 3000 and 1)", hpf_rows, hpf_done);
		// marker file: if it exists after the run, EXITRUN ran even if the printf was lost (gotchas 9d.4)
		file_append(HPF_MARK, strf("EXITRUN ran: rows=%d done=%d\n", hpf_rows, hpf_done), 0);
		return;
	}

	int n;
	var X[7];
	var Y[84];
	n = hpf_n;

	// --- constants built at RUN TIME from integers (gotchas 9d.1, 9d.2) ---
	var lvl = 11;	lvl = lvl / 10;
	var amp = 1;	amp = amp / 100;
	var slp = 1;	slp = slp / 10000;
	var pi_x = 4;	pi_x = pi_x * atan(1);

	// --- inputs from the bar counter (radians); no decimal literal, no PI macro ---
	X[0] = lvl;
	X[1] = lvl + amp * sin(2 * pi_x * n / 5);
	X[2] = lvl + amp * sin(2 * pi_x * n / 10);
	X[3] = lvl + amp * sin(2 * pi_x * n / 20);
	X[4] = lvl + amp * sin(2 * pi_x * n / 40);
	X[5] = lvl + amp * sin(2 * pi_x * n / 100);
	X[6] = lvl + slp * n;

	// --- input series: 7 unconditional calls, fixed order ---
	vars S0 = series(X[0], 3);
	vars S1 = series(X[1], 3);
	vars S2 = series(X[2], 3);
	vars S3 = series(X[3], 3);
	vars S4 = series(X[4], 3);
	vars S5 = series(X[5], 3);
	vars S6 = series(X[6], 3);

	// --- 84 filter calls, variant-major, unconditional, fixed order ---
	Y[0] = HighPassFilter(S0, 20);	// P20 flat
	Y[1] = HighPassFilter(S1, 20);	// P20 s5
	Y[2] = HighPassFilter(S2, 20);	// P20 s10
	Y[3] = HighPassFilter(S3, 20);	// P20 s20
	Y[4] = HighPassFilter(S4, 20);	// P20 s40
	Y[5] = HighPassFilter(S5, 20);	// P20 s100
	Y[6] = HighPassFilter(S6, 20);	// P20 ramp
	Y[7] = HighPassFilter(S0, 30);	// P30 flat
	Y[8] = HighPassFilter(S1, 30);	// P30 s5
	Y[9] = HighPassFilter(S2, 30);	// P30 s10
	Y[10] = HighPassFilter(S3, 30);	// P30 s20
	Y[11] = HighPassFilter(S4, 30);	// P30 s40
	Y[12] = HighPassFilter(S5, 30);	// P30 s100
	Y[13] = HighPassFilter(S6, 30);	// P30 ramp
	Y[14] = HighPassFilter(S0, 48);	// P48 flat
	Y[15] = HighPassFilter(S1, 48);	// P48 s5
	Y[16] = HighPassFilter(S2, 48);	// P48 s10
	Y[17] = HighPassFilter(S3, 48);	// P48 s20
	Y[18] = HighPassFilter(S4, 48);	// P48 s40
	Y[19] = HighPassFilter(S5, 48);	// P48 s100
	Y[20] = HighPassFilter(S6, 48);	// P48 ramp
	Y[21] = HighPassFilter(S0, 125);	// P125 flat
	Y[22] = HighPassFilter(S1, 125);	// P125 s5
	Y[23] = HighPassFilter(S2, 125);	// P125 s10
	Y[24] = HighPassFilter(S3, 125);	// P125 s20
	Y[25] = HighPassFilter(S4, 125);	// P125 s40
	Y[26] = HighPassFilter(S5, 125);	// P125 s100
	Y[27] = HighPassFilter(S6, 125);	// P125 ramp
	Y[28] = hpf_nca(S0, 48);	// NCA flat
	Y[29] = hpf_nca(S1, 48);	// NCA s5
	Y[30] = hpf_nca(S2, 48);	// NCA s10
	Y[31] = hpf_nca(S3, 48);	// NCA s20
	Y[32] = hpf_nca(S4, 48);	// NCA s40
	Y[33] = hpf_nca(S5, 48);	// NCA s100
	Y[34] = hpf_nca(S6, 48);	// NCA ramp
	Y[35] = hpf_ncb(S0, 48);	// NCB flat
	Y[36] = hpf_ncb(S1, 48);	// NCB s5
	Y[37] = hpf_ncb(S2, 48);	// NCB s10
	Y[38] = hpf_ncb(S3, 48);	// NCB s20
	Y[39] = hpf_ncb(S4, 48);	// NCB s40
	Y[40] = hpf_ncb(S5, 48);	// NCB s100
	Y[41] = hpf_ncb(S6, 48);	// NCB ramp
	Y[42] = hpf_ncf(S0, 48);	// NCF flat
	Y[43] = hpf_ncf(S1, 48);	// NCF s5
	Y[44] = hpf_ncf(S2, 48);	// NCF s10
	Y[45] = hpf_ncf(S3, 48);	// NCF s20
	Y[46] = hpf_ncf(S4, 48);	// NCF s40
	Y[47] = hpf_ncf(S5, 48);	// NCF s100
	Y[48] = hpf_ncf(S6, 48);	// NCF ramp
	Y[49] = hpf_ncz(S0, 48);	// NCZ flat
	Y[50] = hpf_ncz(S1, 48);	// NCZ s5
	Y[51] = hpf_ncz(S2, 48);	// NCZ s10
	Y[52] = hpf_ncz(S3, 48);	// NCZ s20
	Y[53] = hpf_ncz(S4, 48);	// NCZ s40
	Y[54] = hpf_ncz(S5, 48);	// NCZ s100
	Y[55] = hpf_ncz(S6, 48);	// NCZ ramp
	Y[56] = hpf_ncs(S0, 48);	// NCS flat
	Y[57] = hpf_ncs(S1, 48);	// NCS s5
	Y[58] = hpf_ncs(S2, 48);	// NCS s10
	Y[59] = hpf_ncs(S3, 48);	// NCS s20
	Y[60] = hpf_ncs(S4, 48);	// NCS s40
	Y[61] = hpf_ncs(S5, 48);	// NCS s100
	Y[62] = hpf_ncs(S6, 48);	// NCS ramp
	Y[63] = hpf_nch(S0, 48);	// NCH flat
	Y[64] = hpf_nch(S1, 48);	// NCH s5
	Y[65] = hpf_nch(S2, 48);	// NCH s10
	Y[66] = hpf_nch(S3, 48);	// NCH s20
	Y[67] = hpf_nch(S4, 48);	// NCH s40
	Y[68] = hpf_nch(S5, 48);	// NCH s100
	Y[69] = hpf_nch(S6, 48);	// NCH ramp
	Y[70] = HighPassFilter(S0, 49);	// NC1 flat
	Y[71] = HighPassFilter(S1, 49);	// NC1 s5
	Y[72] = HighPassFilter(S2, 49);	// NC1 s10
	Y[73] = HighPassFilter(S3, 49);	// NC1 s20
	Y[74] = HighPassFilter(S4, 49);	// NC1 s40
	Y[75] = HighPassFilter(S5, 49);	// NC1 s100
	Y[76] = HighPassFilter(S6, 49);	// NC1 ramp
	Y[77] = hpf_nc2(S0, 20);	// NC2 flat
	Y[78] = hpf_nc2(S1, 20);	// NC2 s5
	Y[79] = hpf_nc2(S2, 20);	// NC2 s10
	Y[80] = hpf_nc2(S3, 20);	// NC2 s20
	Y[81] = hpf_nc2(S4, 20);	// NC2 s40
	Y[82] = hpf_nc2(S5, 20);	// NC2 s100
	Y[83] = hpf_nc2(S6, 20);	// NC2 ramp

	// --- write one row per fed bar ---
	if(!hpf_done) {
		if(!hpf_hdr) {
			file_append(HPF_RAW, "n,clock_close,x_flat,x_s5,x_s10,x_s20,x_s40,x_s100,x_ramp", 0);
			file_append(HPF_RAW, ",y_P20_flat,y_P20_s5,y_P20_s10,y_P20_s20,y_P20_s40,y_P20_s100,y_P20_ramp", 0);
			file_append(HPF_RAW, ",y_P30_flat,y_P30_s5,y_P30_s10,y_P30_s20,y_P30_s40,y_P30_s100,y_P30_ramp", 0);
			file_append(HPF_RAW, ",y_P48_flat,y_P48_s5,y_P48_s10,y_P48_s20,y_P48_s40,y_P48_s100,y_P48_ramp", 0);
			file_append(HPF_RAW, ",y_P125_flat,y_P125_s5,y_P125_s10,y_P125_s20,y_P125_s40,y_P125_s100,y_P125_ramp", 0);
			file_append(HPF_RAW, ",y_NCA_flat,y_NCA_s5,y_NCA_s10,y_NCA_s20,y_NCA_s40,y_NCA_s100,y_NCA_ramp", 0);
			file_append(HPF_RAW, ",y_NCB_flat,y_NCB_s5,y_NCB_s10,y_NCB_s20,y_NCB_s40,y_NCB_s100,y_NCB_ramp", 0);
			file_append(HPF_RAW, ",y_NCF_flat,y_NCF_s5,y_NCF_s10,y_NCF_s20,y_NCF_s40,y_NCF_s100,y_NCF_ramp", 0);
			file_append(HPF_RAW, ",y_NCZ_flat,y_NCZ_s5,y_NCZ_s10,y_NCZ_s20,y_NCZ_s40,y_NCZ_s100,y_NCZ_ramp", 0);
			file_append(HPF_RAW, ",y_NCS_flat,y_NCS_s5,y_NCS_s10,y_NCS_s20,y_NCS_s40,y_NCS_s100,y_NCS_ramp", 0);
			file_append(HPF_RAW, ",y_NCH_flat,y_NCH_s5,y_NCH_s10,y_NCH_s20,y_NCH_s40,y_NCH_s100,y_NCH_ramp", 0);
			file_append(HPF_RAW, ",y_NC1_flat,y_NC1_s5,y_NC1_s10,y_NC1_s20,y_NC1_s40,y_NC1_s100,y_NC1_ramp", 0);
			file_append(HPF_RAW, ",y_NC2_flat,y_NC2_s5,y_NC2_s10,y_NC2_s20,y_NC2_s40,y_NC2_s100,y_NC2_ramp", 0);
			file_append(HPF_RAW, "\n", 0);
			hpf_hdr = 1;
		}
		file_append(HPF_RAW, strf("%d,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", n, priceClose(), X[0], X[1], X[2], X[3], X[4], X[5], X[6]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[0],Y[1],Y[2],Y[3],Y[4],Y[5],Y[6]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[7],Y[8],Y[9],Y[10],Y[11],Y[12],Y[13]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[14],Y[15],Y[16],Y[17],Y[18],Y[19],Y[20]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[21],Y[22],Y[23],Y[24],Y[25],Y[26],Y[27]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[28],Y[29],Y[30],Y[31],Y[32],Y[33],Y[34]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[35],Y[36],Y[37],Y[38],Y[39],Y[40],Y[41]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[42],Y[43],Y[44],Y[45],Y[46],Y[47],Y[48]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[49],Y[50],Y[51],Y[52],Y[53],Y[54],Y[55]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[56],Y[57],Y[58],Y[59],Y[60],Y[61],Y[62]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[63],Y[64],Y[65],Y[66],Y[67],Y[68],Y[69]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[70],Y[71],Y[72],Y[73],Y[74],Y[75],Y[76]), 0);
		file_append(HPF_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[77],Y[78],Y[79],Y[80],Y[81],Y[82],Y[83]), 0);
		file_append(HPF_RAW, "\n", 0);
		hpf_rows += 1;
		if(n == HPF_NBARS - 1) {
			hpf_done = 1;	// latch first; nothing is written after this row
			quit("HPF batch complete: 3000 rows written");
		} else {
			hpf_n += 1;
		}
	}
}
